// Modified by Romaric-py for preventing illegal moves from the book and for
// castling moves.
#include "polyglot.h"
#include "legal_move.h"
#include "polyglot_constants.h"
#include "special_move.h"
#include <stdio.h>
#include <stdlib.h>

#define BOOK_FILENAME "data/book.bin"

// Endianness conversions (native GCC / Clang)
#define SWAP64(x) __builtin_bswap64(x)
#define SWAP16(x) __builtin_bswap16(x)
#define SWAP32(x) __builtin_bswap32(x)

static bool has_polyglot_en_passant_capture(const ChessBoard *board) {
  if (!ENPASSANT_ACTIVE(*board)) {
    return false;
  }

  Coords target = ENPASSANT_POS(*board);
  int source_row = (board->meta.current_turn == CHESS_WHITE)
                       ? (int)target.row + 1
                       : (int)target.row - 1;
  if (source_row < 0 || source_row >= BOARD_SIZE) {
    return false;
  }

  for (int delta = -1; delta <= 1; delta += 2) {
    int source_col = (int)target.col + delta;
    if (source_col >= 0 && source_col < BOARD_SIZE &&
        is_enpassant_move(
            board,
            create_coords((unsigned int)source_row, (unsigned int)source_col),
            target)) {
      return true;
    }
  }
  return false;
}

// Mapping to the Polyglot piece index (0 to 11).
// Polyglot order is black first for each type:
// pawn, knight, bishop, rook, queen, king.
static int get_polyglot_piece_index(PieceName name, ChessColor color) {
  int p = 0;
  switch (name) {
  case PAWN:
    p = 0;
    break;
  case KNIGHT:
    p = 1;
    break;
  case BISHOP:
    p = 2;
    break;
  case ROOK:
    p = 3;
    break;
  case QUEEN:
    p = 4;
    break;
  case KING:
    p = 5;
    break;
  default:
    return -1;
  }
  int color_offset = (color == CHESS_BLACK) ? 0 : 1;
  return (p * 2) + color_offset;
}

uint64_t compute_polyglot_hash(const ChessBoard *board) {
  uint64_t hash = 0ULL;

  // Pieces on the board (indices 0 to 767)
  for (unsigned int row = 0; row < BOARD_SIZE; row++) {
    for (unsigned int col = 0; col < BOARD_SIZE; col++) {
      Piece piece = board->squares[row][col];
      if (piece.name != NONE) {
        int p_index = get_polyglot_piece_index(piece.name, piece.color);
        if (p_index >= 0) {
          // Calculate the square index (0 to 63).
          // Adapt the rank order (row * 8 + col) to the display convention.
          int sq = (7 - row) * 8 + col; // 0 = a1, 63 = h8
          hash ^= polyglot_random[p_index * 64 + sq];
        }
      }
    }
  }

  // Castling rights (indices 768 to 771)
  // Use the BoardMetaData macros and structures.
  if (CASTLE_K(*board, CHESS_WHITE))
    hash ^= polyglot_random[768]; // White King side
  if (CASTLE_Q(*board, CHESS_WHITE))
    hash ^= polyglot_random[769]; // White Queen side
  if (CASTLE_K(*board, CHESS_BLACK))
    hash ^= polyglot_random[770]; // Black King side
  if (CASTLE_Q(*board, CHESS_BLACK))
    hash ^= polyglot_random[771]; // Black Queen side

  // En passant (indices 772 to 779)
  if (has_polyglot_en_passant_capture(board)) {
    unsigned int file = ENPASSANT_POS(*board).col;
    if (file < 8) {
      hash ^= polyglot_random[772 + file];
    }
  }

  // Polyglot includes the side-to-move key when White is to move.
  if (board->meta.current_turn == CHESS_WHITE) {
    hash ^= polyglot_random[780];
  }

  return hash;
}

bool choose_move_from_book(ChessBoard *board, Move *move) {
  // Compute the Polyglot hash for the current position
  uint64_t poly_key = compute_polyglot_hash(board);

  PolyEntry book_entries[32]; // Array to store the book's possible moves
  int num_book_moves =
      get_book_moves(BOOK_FILENAME, poly_key, book_entries, 32);

  if (num_book_moves <= 0) {
    return false; // No book moves found for this position
  }

  // If the book contains moves for this position
  // Select a random move weighted by its 'weight' (move popularity)
  // to vary games and avoid always playing the same rigid move.
  int total_weight = 0;
  for (int i = 0; i < num_book_moves; i++) {
    total_weight += book_entries[i].weight;
  }

  int chosen_index = 0;
  if (total_weight > 0) {
    int r = rand() % total_weight;
    int cumulative = 0;
    for (int i = 0; i < num_book_moves; i++) {
      cumulative += book_entries[i].weight;
      if (r < cumulative) {
        chosen_index = i;
        break;
      }
    }
  }

  *move = polyglot_move_to_engine_move(book_entries[chosen_index].move);

  Piece p = get_piece(board, move->src);
  if (p.name == KING && move->src.row == move->dest.row && move->src.col == 4) {
    if (move->dest.col == 0)
      move->dest.col = 2; // queen side castling
    else if (move->dest.col == 7)
      move->dest.col = 6; // king side castling
  }
  // Never play illegal moves from the book, even if they are in the book.
  if (!is_legal_move(board, move->src, move->dest))
    return false;

  return true;
}

int get_book_moves(const char *filename, uint64_t board_key,
                   PolyEntry *out_entries, int max_entries) {
  FILE *file = fopen(filename, "rb");
  if (!file) {
    perror("Failed to open Polyglot book file");
    return 0;
  }

  fseek(file, 0, SEEK_END);
  long file_size = ftell(file);
  long entry_size = sizeof(PolyEntry);
  long num_entries = file_size / entry_size;

  if (num_entries <= 0) {
    fclose(file);
    return 0;
  }

  // Polyglot stores keys in big-endian order. Decode each key before
  // comparing it, so the binary search uses the file's logical ordering.
  uint64_t target_key = board_key;

  // Binary search
  long low = 0;
  long high = num_entries - 1;
  long match_index = -1;

  while (low <= high) {
    long mid = low + (high - low) / 2;
    fseek(file, mid * entry_size, SEEK_SET);

    PolyEntry entry;
    if (fread(&entry, entry_size, 1, file) != 1)
      break;

    uint64_t entry_key = SWAP64(entry.key);
    if (entry_key == target_key) {
      match_index = mid;
      break;
    } else if (entry_key < target_key) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  if (match_index == -1) {
    fclose(file);
    return 0;
  }

  // Move backward to find the first occurrence if multiple entries share the
  // same key.
  long start_index = match_index;
  while (start_index > 0) {
    fseek(file, (start_index - 1) * entry_size, SEEK_SET);
    PolyEntry entry;
    if (fread(&entry, entry_size, 1, file) != 1) {
      break;
    }
    if (SWAP64(entry.key) == target_key) {
      start_index--;
    } else {
      break;
    }
  }

  // Retrieve the moves.
  int count = 0;
  long curr = start_index;
  while (curr < num_entries && count < max_entries) {
    fseek(file, curr * entry_size, SEEK_SET);
    PolyEntry entry;
    if (fread(&entry, entry_size, 1, file) != 1)
      break;

    if (SWAP64(entry.key) != target_key)
      break;

    out_entries[count].key = target_key;
    out_entries[count].move = SWAP16(entry.move);
    out_entries[count].weight = SWAP16(entry.weight);
    out_entries[count].learn = SWAP32(entry.learn);

    count++;
    curr++;
  }

  fclose(file);
  return count;
}

Move polyglot_move_to_engine_move(uint16_t poly_move) {
  Move move;
  int dest_sq = poly_move & 0x3F;
  int orig_sq = (poly_move >> 6) & 0x3F;
  int promo = (poly_move >> 12) & 0x7;

  move.src.row = 7 - (orig_sq / 8);
  move.src.col = orig_sq % 8;
  move.dest.row = 7 - (dest_sq / 8);
  move.dest.col = dest_sq % 8;

  move.is_capture = false; // Evaluated by the engine logic if needed.

  switch (promo) {
  case 1:
    move.promotion = KNIGHT;
    break;
  case 2:
    move.promotion = BISHOP;
    break;
  case 3:
    move.promotion = ROOK;
    break;
  case 4:
    move.promotion = QUEEN;
    break;
  default:
    move.promotion = NONE;
    break;
  }

  return move;
}